 static boolean same(Object a,Object b){if(a instanceof Number&&b instanceof Number){double x=d(a),y=d(b);return Double.isFinite(x)&&Double.isFinite(y)&&Math.abs(x-y)<=.00005*Math.max(1,Math.abs(y));}return Objects.equals(a,b);}
