 static Map<String,Object> map(Object... kv){Map<String,Object> m=new LinkedHashMap<>();for(int i=0;i<kv.length;i+=2)m.put(kv[i].toString(),kv[i+1]);return m;}
 static byte[] bytes(InputStream in,int count)throws IOException{require(count>=0&&count<=LIMIT,"Oversized field");byte[] b=new byte[count];new DataInputStream(in).readFully(b);return b;}
