  static List<Object> array(DataInputStream in,int count,int depth)throws Exception{require(count<=in.available(),"Truncated array");List<Object>a=new ArrayList<>();for(int i=0;i<count;i++)a.add(read(in,depth+1));return a;}
  static Map<String,Object> object(DataInputStream in,int count,int depth)throws Exception{require(count<=in.available()/2,"Truncated map");Map<String,Object>m=new LinkedHashMap<>();for(int i=0;i<count;i++){String k=key(read(in,depth+1));require(!m.containsKey(k),"Duplicate map key");m.put(k,read(in,depth+1));}return m;}
  static byte[] encode(Object o)throws Exception{ByteArrayOutputStream b=new ByteArrayOutputStream();write(new DataOutputStream(b),o,0);require(b.size()<=LIMIT,"MessagePack output too large");return b.toByteArray();}
  static void size(DataOutputStream out,int n,int small,int large)throws Exception{require(n>=0&&n<=LIMIT,"Oversized output");if(n<=65535){out.writeByte(small);out.writeShort(n);}else{out.writeByte(large);out.writeInt(n);}}
